import assert from 'node:assert/strict'
import test from 'node:test'
import { mkdtemp, rm, mkdir, writeFile } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { execFileSync } from 'node:child_process'

import { start, startJob, readJob, getJob, listJobs, createRunnerServer, startRunnerServer } from '../jobs.mjs'

function makeRepo() {
  const dir = mkdtempSync(join(tmpdir(), 'jul231-repo-'))
  execFileSync('git', ['-C', dir, 'init', '-q'], { stdio: 'ignore' })
  execFileSync('git', ['-C', dir, 'config', 'user.email', 't@e.com'])
  execFileSync('git', ['-C', dir, 'config', 'user.name', 'T'])
  writeFile(join(dir, 'README.md'), 'base\n')
  execFileSync('git', ['-C', dir, 'add', '-A'], { cwd: dir })
  execFileSync('git', ['-C', dir, 'commit', '-q', '-m', 'base'], { cwd: dir })
  const base = execFileSync('git', ['-C', dir, 'rev-parse', 'HEAD']).toString().trim()
  return { dir, base }
}

import { mkdtempSync } from 'node:fs'

test('job start/readback/idempotence', async () => {
  const repo = makeRepo()
  const jobsDir = await mkdtemp(join(tmpdir(), 'jul231-jobs-'))
  const snapshot = { runId: 'JUL-231', snapshot: { card: 'JUL-231', roles: { orchestrator: { model: 'm' }, coder: { model: 'm' } } } }
  const fakeSpawn = (cmd, args, opts) => ({ pid: 4242, unref() {} })
  try {
    const job = await start(snapshot, { jobsDir, repo: repo.dir, base: repo.base, spawn: fakeSpawn, workerPath: '/tmp/worker.mjs' })
    assert.equal(job.runId, 'JUL-231')
    assert.equal(job.state, 'running')
    assert.equal(job.workerPid, 4242)
    const read = await readJob('JUL-231', { jobsDir })
    assert.equal(read.runId, 'JUL-231')
    assert.equal(read.worktree.includes('worktree'), true)
    const again = await startJob(snapshot, { jobsDir, repo: repo.dir, base: repo.base, spawn: fakeSpawn, workerPath: '/tmp/worker.mjs' })
    assert.equal(again.workerPid, 4242)
    const list = await listJobs({ jobsDir })
    assert.equal(list.length, 1)
  } finally {
    await rm(repo.dir, { recursive: true, force: true })
    await rm(jobsDir, { recursive: true, force: true })
  }
})

test('job validation rejects bad runId and roles', async () => {
  const jobsDir = await mkdtemp(join(tmpdir(), 'jul231-jobs-'))
  try {
    await assert.rejects(() => start({ runId: '', snapshot: { card: 'x', roles: { orchestrator: { model: 'm' }, coder: { model: 'm' } } } }, { jobsDir, spawn: () => ({ pid: 1, unref() {} }) }), /runId/i)
    await assert.rejects(() => start({ runId: 'R', snapshot: { card: 'x', roles: { orchestrator: { model: 'm' } } } }, { jobsDir, spawn: () => ({ pid: 1, unref() {} }) }), /role/i)
  } finally { await rm(jobsDir, { recursive: true, force: true }) }
})

test('runner server endpoints', async () => {
  const repo = makeRepo()
  const jobsDir = await mkdtemp(join(tmpdir(), 'jul231-jobs-'))
  const server = await startRunnerServer({ jobsDir, repo: repo.dir, base: repo.base, port: 0, spawn: () => ({ pid: 7, unref() {} }), workerPath: '/tmp/worker.mjs' })
  const addr = server.address()
  const base = `http://127.0.0.1:${addr.port}`
  try {
    const health = await fetch(base + '/health')
    assert.equal(health.status, 200)
    const snap = { runId: 'R2', snapshot: { card: 'C', roles: { orchestrator: { model: 'm' }, coder: { model: 'm' } } } }
    const res = await fetch(base + '/jobs', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(snap) })
    assert.equal(res.status, 200)
    const job = await res.json()
    assert.equal(job.runId, 'R2')
    const get = await fetch(base + '/jobs/R2')
    assert.equal(get.status, 200)
    const list = await fetch(base + '/jobs')
    const arr = await list.json()
    assert.ok(Array.isArray(arr))
  } finally {
    server.close()
    await rm(repo.dir, { recursive: true, force: true })
    await rm(jobsDir, { recursive: true, force: true })
  }
})

import { spawn as defaultSpawn } from 'node:child_process'
import { execFile as execFileCb } from 'node:child_process'
import { promisify } from 'node:util'
import { mkdtemp, mkdir, readFile, writeFile, rename, readdir, stat, openSync, closeSync } from 'node:fs/promises'
import { join, resolve, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'
import { createServer } from 'node:http'

const execFile = promisify(execFileCb)
const __dirname = dirname(fileURLToPath(import.meta.url))

let lastJobsDir = null

function resolveOpts(options = {}) {
  const jobsDir = options.jobsDir ?? options.dir ?? options.root ?? options.stateDir ?? options.storageDir ?? process.env.BUILD_RUNNER_JOBS_DIR ?? process.env.JOBS_DIR ?? null
  const resolvedJobsDir = jobsDir ? resolve(jobsDir) : (lastJobsDir ?? resolve(process.cwd(), '.build-jobs'))
  if (jobsDir) lastJobsDir = resolvedJobsDir
  const repo = options.repo ?? options.repository ?? options.repoPath ?? options.repositoryPath ?? process.env.BUILD_RUNNER_REPO ?? process.env.REPO_PATH ?? process.cwd()
  const base = options.base ?? options.baseCommit ?? options.baseRef ?? options.head ?? options.ref ?? process.env.BUILD_RUNNER_BASE ?? process.env.BASE_COMMIT ?? null
  const workerPath = options.workerPath ?? options.worker ?? process.env.BUILD_RUNNER_WORKER ?? join(__dirname, 'worker.mjs')
  const spawnImpl = options.spawn ?? options.spawnImpl ?? options.processSpawn ?? defaultSpawn
  const env = options.env ?? process.env
  const port = options.port ?? (process.env.BUILD_RUNNER_PORT ? Number(process.env.BUILD_RUNNER_PORT) : 8787)
  return { jobsDir: resolvedJobsDir, repo: resolve(repo), base, workerPath, spawnImpl, env, port }
}

function normalize(input) {
  if (!input || typeof input !== 'object' || Array.isArray(input)) throw new Error('snapshot required')
  const runId = input.runId ?? input.id ?? input.jobId
  if (typeof runId !== 'string' || !runId.trim()) throw new Error('runId required')
  const savedSnapshot = (input.snapshot && typeof input.snapshot === 'object') ? input.snapshot : input
  const roles = savedSnapshot.roles ?? input.roles
  if (!roles || typeof roles !== 'object' || Array.isArray(roles)) throw new Error('roles required')
  const keys = Object.keys(roles)
  if (keys.length !== 2 || !keys.includes('orchestrator') || !keys.includes('coder') || keys.some(k => k !== 'orchestrator' && k !== 'coder')) {
    throw new Error('exact two roles required: orchestrator and coder')
  }
  for (const key of ['orchestrator', 'coder']) {
    const role = roles[key]
    const model = typeof role === 'string' ? role : role?.model
    if (typeof model !== 'string' || !model.trim()) throw new Error(`${key} role requires model`)
  }
  return { runId: runId.trim(), savedSnapshot }
}

function jobPath(jobsDir, runId) { return join(jobsDir, runId, 'job.json') }

async function readJobFile(jobsDir, runId) {
  const raw = await readFile(jobPath(jobsDir, runId), 'utf8')
  return JSON.parse(raw)
}

async function writeJobFile(jobsDir, runId, job) {
  const dir = join(jobsDir, runId)
  await mkdir(dir, { recursive: true })
  const tmp = jobPath(jobsDir, runId) + '.tmp'
  await writeFile(tmp, JSON.stringify(job, null, 2))
  await rename(tmp, jobPath(jobsDir, runId))
}

async function resolveBase(repo, base) {
  if (base) return String(base).trim()
  const { stdout } = await execFile('git', ['-C', repo, 'rev-parse', 'HEAD'])
  return stdout.trim()
}

export async function start(input, options = {}) {
  const opts = resolveOpts(options)
  const { runId, savedSnapshot } = normalize(input)
  // duplicate
  try {
    await stat(jobPath(opts.jobsDir, runId))
    return await readJobFile(opts.jobsDir, runId)
  } catch {}
  const baseCommit = await resolveBase(opts.repo, opts.base)
  const jobDir = join(opts.jobsDir, runId)
  await mkdir(jobDir, { recursive: true })
  const worktree = join(jobDir, 'worktree')
  await execFile('git', ['-C', opts.repo, 'worktree', 'add', '--detach', worktree, baseCommit])
  // save snapshot
  await writeFile(join(jobDir, 'snapshot.json'), JSON.stringify(input, null, 2))
  const job = {
    runId,
    snapshot: savedSnapshot,
    worktree,
    baseCommit,
    state: 'running',
    runnerPid: process.pid,
    workerPid: null,
    result: null,
    error: null,
    createdAt: new Date().toISOString(),
  }
  await writeJobFile(opts.jobsDir, runId, job)
  const logFd = openSync(join(jobDir, 'worker.log'), 'a')
  let child
  try {
    child = opts.spawnImpl(process.execPath, [opts.workerPath, '--job-dir', jobDir], {
      stdio: ['ignore', logFd, logFd],
      env: opts.env,
    })
  } finally {
    closeSync(logFd)
  }
  if (child && typeof child.unref === 'function') child.unref()
  job.workerPid = child?.pid ?? null
  await writeJobFile(opts.jobsDir, runId, job)
  return await readJobFile(opts.jobsDir, runId)
}

export const startJob = start

export async function readJob(runId, options = {}) {
  const opts = resolveOpts(options)
  return await readJobFile(opts.jobsDir, runId)
}
export const getJob = readJob

export async function listJobs(options = {}) {
  const opts = resolveOpts(options)
  const entries = await readdir(opts.jobsDir, { withFileTypes: true }).catch(() => [])
  const jobs = []
  for (const entry of entries) {
    if (!entry.isDirectory()) continue
    try {
      const job = await readJobFile(opts.jobsDir, entry.name)
      jobs.push(job)
    } catch {}
  }
  return jobs
}

function parseUrl(url) {
  const u = new URL(url, 'http://localhost')
  return { pathname: u.pathname }
}

export function createRunnerServer(options = {}) {
  const opts = resolveOpts(options)
  const server = createServer(async (req, res) => {
    const { pathname } = parseUrl(req.url)
    try {
      if (req.method === 'GET' && pathname === '/health') {
        res.writeHead(200, { 'content-type': 'application/json' })
        res.end(JSON.stringify({ ok: true }))
        return
      }
      if (req.method === 'GET' && pathname === '/jobs') {
        const jobs = await listJobs(opts)
        res.writeHead(200, { 'content-type': 'application/json' })
        res.end(JSON.stringify(jobs))
        return
      }
      if (req.method === 'POST' && pathname === '/jobs') {
        const chunks = []
        for await (const chunk of req) chunks.push(chunk)
        const body = JSON.parse(Buffer.concat(chunks).toString('utf8') || '{}')
        const job = await start(body, opts)
        res.writeHead(200, { 'content-type': 'application/json' })
        res.end(JSON.stringify(job))
        return
      }
      const match = pathname.match(/^\/jobs\/([^/]+)$/)
      if (req.method === 'GET' && match) {
        const job = await readJob(decodeURIComponent(match[1]), opts)
        res.writeHead(200, { 'content-type': 'application/json' })
        res.end(JSON.stringify(job))
        return
      }
      res.writeHead(404, { 'content-type': 'application/json' })
      res.end(JSON.stringify({ error: 'not found' }))
    } catch (error) {
      res.writeHead(400, { 'content-type': 'application/json' })
      res.end(JSON.stringify({ error: error.message }))
    }
  })
  server.jobsOptions = opts
  return server
}

export async function startRunnerServer(options = {}) {
  const server = createRunnerServer(options)
  const opts = server.jobsOptions
  await new Promise((resolve, reject) => {
    server.listen(opts.port, '127.0.0.1', (err) => err ? reject(err) : resolve())
  })
  return server
}
export const startServer = startRunnerServer
export const runnerServer = createRunnerServer

import { readFile, mkdir, realpath, openSync, closeSync } from 'node:fs/promises'
import { join, resolve, relative, isAbsolute, dirname, basename } from 'node:path'
import { fileURLToPath } from 'node:url'
import { CardLedger } from './ledger.mjs'
import { createTransport } from './transport.mjs'

const quote = value => "'" + String(value).replaceAll("'", "'\\''") + "'"
let opened = false

export async function openRunner({ card, settingsPath, cwd, stateDir, role = 'builder', hostInstructions, subagents, helpers }) {
  if (opened) throw Error('one runner per process required')
  if (!/^[A-Z]+-\d+$/.test(card)) throw Error('valid card ID required')
  const settings = JSON.parse(await readFile(settingsPath, 'utf8'))
  if (!settings.roles?.[role] || !settings.models?.[settings.roles[role]]) throw Error('configured role required')
  cwd = await realpath(cwd)
  stateDir = resolve(stateDir)
  await mkdir(stateDir, { recursive: true, mode: 0o700 })
  stateDir = await realpath(stateDir)
  const inside = relative(cwd, stateDir)
  if (!inside.startsWith('..') && !isAbsolute(inside)) throw Error('adapter state must be outside builder workspace')
  const appDir = join(stateDir, 'sdk')
  const sdkHome = join(stateDir, 'home')
  const commandHome = join(cwd, '.builder-home')
  await mkdir(commandHome, { recursive: true })
  await mkdir(sdkHome, { recursive: true, mode: 0o700 })
  await mkdir(appDir, { recursive: true, mode: 0o700 })
  const runtimeProviders = (settings.providers ?? []).map(provider => {
    const { credentialEnv, ...publicProvider } = provider
    const apiKey = credentialEnv ? process.env[credentialEnv] : undefined
    if (credentialEnv && !apiKey) throw Error('provider unavailable: runtime credential missing')
    if ('apiKey' in publicProvider || 'headers' in publicProvider) throw Error('provider settings must not contain credentials')
    return { ...publicProvider, ...(apiKey ? { apiKey } : {}) }
  })
  let authPath = settings.authPath ? resolve(settings.authPath) : join(stateDir, 'auth.json')
  await mkdir(dirname(authPath), { recursive: true, mode: 0o700 })
  try { authPath = await realpath(authPath) } catch (error) {
    if (error.code !== 'ENOENT') throw error
    authPath = join(await realpath(dirname(authPath)), basename(authPath))
  }
  const authInside = relative(cwd, authPath)
  if (!authInside.startsWith('..') && !isAbsolute(authInside)) throw Error('credentials must be outside builder workspace')
  const path = process.env.PATH
  for (const key of Object.keys(process.env)) delete process.env[key]
  Object.assign(process.env, { PATH: path ?? '/usr/local/bin:/usr/bin:/bin', HOME: sdkHome, LANG: 'C.UTF-8', MASTRA_APP_DATA_DIR: appDir })
  if (settings.memory === false) process.env.MASTRACODE_DISABLE_OBSERVATIONAL_MEMORY = '1'
  const ledger = new CardLedger({ path: join(stateDir, 'cards.sqlite'), card })
  const originalFetch = globalThis.fetch
  globalThis.fetch = createTransport({ settings, ledger, role, fetch: originalFetch, trial: true })
  opened = true
  let runtime
  let workspace
  const providedSubagents = (subagents ?? helpers)
  try {
    const [{ bootLocalAgentController, runMC }, { setCredentialStoreProvider }, { setCustomProvidersSource }, { AuthStorage }, { loadSettings, saveSettings }, { Workspace, LocalFilesystem, LocalSandbox, createWorkspaceTools }, { RequestContext }] = await Promise.all([
      import('@mastra/code-sdk'),
      import('@mastra/code-sdk/agents/credential-resolver'),
      import('@mastra/code-sdk/agents/custom-provider-source'),
      import('@mastra/code-sdk/auth/storage'),
      import('@mastra/code-sdk/onboarding/settings'),
      import('@mastra/core/workspace'),
      import('@mastra/core/request-context'),
    ])
    const auth = new AuthStorage(authPath)
    auth.allowEnvironmentFallback = false
    setCredentialStoreProvider(() => auth, async () => ({ userId: card, credentialScope: 'user' }))
    setCustomProvidersSource(() => runtimeProviders)
    const sdkSettings = loadSettings()
    sdkSettings.models.activeOmPackId = null
    sdkSettings.models.omModelOverride = 'auto'
    sdkSettings.models.observerModelSelection = 'auto'
    sdkSettings.models.reflectorModelSelection = 'auto'
    sdkSettings.models.observerModelOverride = null
    sdkSettings.models.reflectorModelOverride = null
    sdkSettings.models.omObservationThreshold = null
    sdkSettings.models.omReflectionThreshold = null
    sdkSettings.customProviders = runtimeProviders.map(({ apiKey, ...provider }) => provider)
    saveSettings(sdkSettings)
    const sandbox = new LocalSandbox({ workingDirectory: cwd, env: { HOME: commandHome, TMPDIR: commandHome }, timeout: 30_000 })
    const spawn = sandbox.processes.spawn.bind(sandbox.processes)
    const launcher = fileURLToPath(new URL('./command-boundary.py', import.meta.url))
    sandbox.processes.spawn = (command, options = {}) => {
      const config = JSON.stringify({ workspace: cwd, home: commandHome, cwd: resolve(cwd, options.cwd ?? '.'), executable: process.execPath })
      return spawn(`/usr/bin/python3 ${quote(launcher)} ${quote(config)} ${quote(command)}`, { ...options, env: {} })
    }
    workspace = new Workspace({ filesystem: new LocalFilesystem({ basePath: cwd, contained: true }), sandbox, tools: { mastra_workspace_execute_command: { name: 'execute_command' } }, skills: ['.agents/skills'] })
    await workspace.init()
    runtime = await bootLocalAgentController({
      cwd, homeDir: sdkHome, workspace, modes: false, subagents: providedSubagents, intervalHandlers: [],
      hostInstructions, disableMcp: true, disablePlugins: true, disableEnvFile: true, disableHooks: true, disableGithubSignals: true,
    })
    const tools = await createWorkspaceTools(workspace)
    const availableSkills = await workspace.skills?.list?.() ?? []
    return {
      snapshot: () => ledger.snapshot(),
      execute: async command => tools.execute_command.execute({ command }, {}),
      memory: async () => {
        const requestContext = new RequestContext()
        requestContext.set('controller', { session: { modelId: runtime.session.model.get() }, state: runtime.session.state.get(), getState: () => runtime.session.state.get(), threadId: runtime.session.thread.requireId() })
        return typeof runtime.memory === 'function' ? runtime.memory({ requestContext }) : runtime.memory
      },
      skills: workspace.skills,
      availableSkills,
      runtime,
      async run({ prompt, threadId, maxTurns = 6, timeoutMs = 180_000 }) {
        if (typeof prompt !== 'string' || !prompt.trim()) throw Error('prompt required')
        const thread = threadId ? { id: threadId } : await runtime.session.thread.create({ title: card })
        await runtime.session.model.switch(settings.roles[role])
        const result = await runMC({ controller: runtime.controller, session: runtime.session, thread: { id: thread.id }, prompt, maxTurns, timeoutMs }).result
        return { result, threadId: thread.id, account: ledger.snapshot() }
      },
      async close() {
        await runtime.memory?.settled?.()
        await runtime.controller.destroy()
        await runtime.observability.shutdown()
        await workspace.destroy()
        setCredentialStoreProvider(undefined)
        setCustomProvidersSource(undefined)
        globalThis.fetch = originalFetch
        ledger.close()
      },
    }
  } catch (error) {
    await runtime?.controller.destroy()
    await workspace?.destroy()
    globalThis.fetch = originalFetch
    ledger.close()
    throw error
  }
}

import { readFile, writeFile, rename, mkdir } from 'node:fs/promises'
import { join, resolve, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'
import { execFile as execFileCb } from 'node:child_process'
import { promisify } from 'node:util'
import { openRunner } from './adapter.mjs'

const execFile = promisify(execFileCb)
const __dirname = dirname(fileURLToPath(import.meta.url))

function argValue(name) {
  const idx = process.argv.indexOf(name)
  if (idx !== -1 && process.argv[idx + 1]) return process.argv[idx + 1]
  return null
}

const jobDir = resolve(argValue('--job-dir') ?? process.env.BUILD_RUNNER_JOB_DIR ?? process.argv[2] ?? '')
if (!jobDir) { console.error('job dir required'); process.exit(2) }

async function readJob() {
  return JSON.parse(await readFile(join(jobDir, 'job.json'), 'utf8'))
}

async function writeJob(job) {
  const tmp = join(jobDir, 'job.json.tmp')
  await writeFile(tmp, JSON.stringify(job, null, 2))
  await rename(tmp, join(jobDir, 'job.json'))
}

function resolveSettingsPath() {
  const candidates = [
    process.env.BUILD_RUNNER_SETTINGS,
    process.env.MACHINE_SETTINGS,
    process.env.SETTINGS_PATH,
    resolve(process.cwd(), 'ops/build-runner/machine-settings.json'),
    resolve(process.cwd(), 'ops/build-runner/settings.json'),
    resolve(__dirname, 'machine-settings.json'),
    resolve(__dirname, 'settings.json'),
  ].filter(Boolean)
  return candidates.find(p => { try { return !!p } catch { return false } }) || candidates[0]
}
// sync exists check
import { existsSync } from 'node:fs'
function settingsPath() {
  const candidates = [
    process.env.BUILD_RUNNER_SETTINGS,
    process.env.MACHINE_SETTINGS,
    process.env.SETTINGS_PATH,
    resolve(process.cwd(), 'ops/build-runner/machine-settings.json'),
    resolve(process.cwd(), 'ops/build-runner/settings.json'),
    resolve(__dirname, 'machine-settings.json'),
    resolve(__dirname, 'settings.json'),
  ].filter(Boolean)
  return candidates.find(p => existsSync(p)) || candidates[0]
}

function resolveModelKey(settings, raw) {
  if (typeof raw !== 'string') raw = raw?.model
  if (!raw) return undefined
  if (settings.models?.[raw]) return raw
  for (const key of Object.keys(settings.models ?? {})) {
    if (settings.models[key].wireModel === raw) return key
  }
  // try suffix/prefix
  for (const key of Object.keys(settings.models ?? {})) {
    if (key.endsWith(raw) || raw.endsWith(key)) return key
  }
  return raw
}

function paidModelKey(settings) {
  for (const [key, spec] of Object.entries(settings.models ?? {})) {
    if (Object.values(spec.price ?? {}).some(v => Number(v) > 0)) return key
  }
  return undefined
}

async function main() {
  const job = await readJob()
  const snapshot = job.snapshot?.snapshot ?? job.snapshot ?? {}
  const card = snapshot.card ?? job.snapshot?.card
  const rawRoles = snapshot.roles ?? {}
  const settingsPathValue = settingsPath()
  const settings = JSON.parse(await readFile(settingsPathValue, 'utf8'))
  const orchestratorModel = resolveModelKey(settings, rawRoles.orchestrator)
  const coderModel = resolveModelKey(settings, rawRoles.coder)
  settings.roles = { orchestrator: orchestratorModel, coder: coderModel }
  // remove other roles
  const machineryProof = settings.machineryProof === true

  const deepseekModel = paidModelKey(settings)

  // card instructions
  let cardInstructions = ''
  const cardPaths = [
    resolve(process.cwd(), 'docs/agents', card, 'card.md'),
    resolve(__dirname, '..', '..', 'docs', 'agents', card, 'card.md'),
  ]
  for (const p of cardPaths) {
    try { cardInstructions = await readFile(p, 'utf8'); break } catch {}
  }

  const helpers = [
    { id: 'coder', name: 'Coder', description: 'Implements the build.', instructions: 'Implement the requested build changes in the worktree.', defaultModelId: coderModel, allowedWorkspaceTools: ['execute_command', 'mastra_workspace_read_file', 'mastra_workspace_write_file', 'mastra_workspace_edit_file', 'mastra_workspace_list_files'] },
    { id: 'reviewer', name: 'Internal Reviewer', description: 'Reviews and proves the build.', instructions: 'Review and prove the build changes; report any errors.', defaultModelId: coderModel },
  ]
  if (deepseekModel) {
    helpers.push({ id: 'cap-check', name: 'Cap Check', description: 'Cap check helper.', instructions: 'Run a trivial request to check the cap.', defaultModelId: deepseekModel })
  }

  const stateDir = join(jobDir, 'state')
  await mkdir(stateDir, { recursive: true })

  const runner = await openRunner({
    card,
    settingsPath: settingsPathValue,
    cwd: job.worktree,
    stateDir,
    role: 'orchestrator',
    hostInstructions: cardInstructions,
    subagents: helpers,
  })

  const events = []
  const unsubscribe = runner.runtime.session.subscribe((e) => {
    if (typeof e?.type === 'string' && /tool|subagent|agent/i.test(e.type)) events.push(e)
  })

  let result
  try {
    const prompt = `You are the orchestrator for ${card}.\n${cardInstructions}\n\nDelegate the real build to the coder helper, then internal review/proof to the reviewer helper, then run the cap-check helper once. Report success when complete.`
    result = await runner.run({ prompt, maxTurns: 30, timeoutMs: 300000 })
  } finally {
    unsubscribe()
  }

  // git diff nonempty before commit
  let diffOut = ''
  try {
    const { stdout } = await execFile('git', ['-C', job.worktree, 'status', '--porcelain'])
    diffOut = stdout.trim()
  } catch (e) { diffOut = '' }

  const account = result?.account ?? runner.snapshot?.() ?? {}
  const spentNano = account?.spentNano ?? 0

  const hasCoder = events.some(e => JSON.stringify(e).toLowerCase().includes('coder'))
  const hasReviewer = events.some(e => JSON.stringify(e).toLowerCase().includes('reviewer') || JSON.stringify(e).toLowerCase().includes('review'))
  const reviewerErrors = events.some(e => {
    try { return e?.isError === true && JSON.stringify(e).toLowerCase().includes('review') } catch { return false }
  })
  const modelNow = runner.runtime.session.model.get()

  let failure = null
  if (result?.result?.status !== 'completed') failure = new Error('session not completed')
  else if (!diffOut) failure = new Error('empty candidate diff')
  else if (!hasCoder) failure = new Error('no coder activity')
  else if (!hasReviewer) failure = new Error('no reviewer activity')
  else if (reviewerErrors) failure = new Error('reviewer error')
  else if (modelNow !== orchestratorModel) failure = new Error('model identity differs')
  else if (spentNano !== 0) failure = new Error('nonzero spent')
  else if (!result?.result?.text) failure = new Error('incomplete result')

  if (failure) {
    await runner.close()
    job.state = 'failed'
    job.error = { message: failure.message }
    await writeJob(job)
    process.exitCode = 1
    return
  }

