  const cand = candidateCommit.trim()

  // clean candidate
  const { stdout: statusAfter } = await execFile('git', ['-C', job.worktree, 'status', '--porcelain'])
  if (statusAfter.trim()) {
    await runner.close()
    job.state = 'failed'
    job.error = { message: 'candidate not clean' }
    await writeJob(job)
    process.exitCode = 1
    return
  }
  // descendant base
  try {
    await execFile('git', ['-C', job.worktree, 'merge-base', '--is-ancestor', job.baseCommit, cand])
  } catch {
    await runner.close()
    job.state = 'failed'
    job.error = { message: 'candidate not descendant of base' }
    await writeJob(job)
    process.exitCode = 1
    return
  }

  await runner.close()

  const successResult = {
    card,
    models: { orchestrator: orchestratorModel, coder: coderModel },
    orchestratorModel,
    coderModel,
    worktree: job.worktree,
    candidateCommit: cand,
    baseCommit: job.baseCommit,
    account: { spentNano },
    spentNano,
    internalReview: { events, hasCoder, hasReviewer },
    downstreamReviewStarted: false,
    completedAt: new Date().toISOString(),
    state: 'ready-for-review',
  }

  job.state = 'ready-for-review'
  job.result = successResult
  job.error = null
  await writeJob(job)
}

main().catch(async (error) => {
  try {
    const job = await readJob()
    job.state = 'failed'
    job.error = { message: error.message, stack: error.stack }
    await writeJob(job)
  } catch {}
  console.error(error)
  process.exitCode = 1
})

